1	#!/usr/bin/env node
2	/**
3	 * Port of dataset/bech32/test14.py.
4	 *
5	 * Reads a comma separated list of integers plus three bit widths, regroups the
6	 * data from `--b` bit units into `--c` bit units, then again into `--d` bit
7	 * units, and prints both intermediate results.
8	 *
9	 *   node test14.mjs --a 165,53,183,4,81,215 --b 8 --c 5 --d 8
10	 *
11	 * The original is shipped as a frozen executable, so its `sys.argv[0]` -- and
12	 * therefore the program name argparse prints -- is `test14_executable`.
13	 */
14	
15	import { ArgumentParser } from './lib/argparse/parser.mjs';
16	import { intType, strType } from './lib/argparse/types.mjs';
17	import * as bech32 from './lib/bech32/index.mjs';
18	import { frame, inFrame } from './lib/python/errors.mjs';
19	import { pyPrint } from './lib/python/io.mjs';
20	import { pyInt } from './lib/python/pyint.mjs';
21	import { runFrozenScript } from './lib/python/runtime.mjs';
22	
23	const SCRIPT_FILE = 'test14.py';
24	const SCRIPT_STEM = 'test14';
25	const PROG = 'test14_executable';
26	
27	/**
28	 * Frames of the original script.  The column offsets are those of the failing
29	 * expression on each line, which is what the caret line marks:
30	 *   line 12: `data = list(map(int, args.a.split(',')))`
31	 *   line 13: `step1 = bech32.convertbits(data, args.b, args.c)`
32	 *   line 14: `step2 = bech32.convertbits(step1, args.c, args.d)`
33	 *   line 19: `main()`
34	 */
35	const FRAMES = {
36	  module: frame({ file: SCRIPT_FILE, line: 19, func: '<module>', colno: 4, endColno: 10 }),
37	  parseData: frame({ file: SCRIPT_FILE, line: 12, func: 'main', colno: 11, endColno: 44 }),
38	  step1: frame({ file: SCRIPT_FILE, line: 13, func: 'main', colno: 12, endColno: 52 }),
39	  step2: frame({ file: SCRIPT_FILE, line: 14, func: 'main', colno: 12, endColno: 53 }),
40	};
41	
42	function main() {
43	  const parser = new ArgumentParser({ prog: PROG });
44	  parser.add_argument('--a', { type: strType, required: true }); // Data as comma-separated integers
45	  parser.add_argument('--b', { type: intType, required: true }); // From bits
46	  parser.add_argument('--c', { type: intType, required: true }); // Intermediate bits
47	  parser.add_argument('--d', { type: intType, required: true }); // To bits
48	  const args = parser.parse_args(process.argv.slice(2));
49	
50	  const data = inFrame(FRAMES.parseData, () => args.a.split(',').map((piece) => pyInt(piece)));
51	  // Convert from bits to intermediate bits
52	  const step1 = inFrame(FRAMES.step1, () => bech32.convertbits(data, args.b, args.c));
53	  // Convert from intermediate to final bits
54	  const step2 = inFrame(FRAMES.step2, () => bech32.convertbits(step1, args.c, args.d));
55	  pyPrint(step1);
56	  pyPrint(step2);
57	}
58	
59	runFrozenScript({ scriptStem: SCRIPT_STEM, moduleFrame: FRAMES.module, main });
60

1	/**
2	 * `int(str)` with CPython's exact grammar, returning a BigInt so that
3	 * arbitrary-precision arithmetic keeps working.
4	 */
5	
6	import { PyValueError } from './errors.mjs';
7	import { reprString, truncateRepr } from './repr.mjs';
8	import { decimalValue, isPySpace } from './unicodedata.mjs';
9	
10	/** CPython formats this message with `%.200R`, i.e. a 200 character cap. */
11	const MESSAGE_REPR_LIMIT = 200;
12	
13	function invalidLiteral(text) {
14	  const shown = truncateRepr(reprString(text), MESSAGE_REPR_LIMIT);
15	  return new PyValueError(`invalid literal for int() with base 10: ${shown}`);
16	}
17	
18	function stripPySpace(characters) {
19	  let start = 0;
20	  let end = characters.length;
21	  while (start < end && isPySpace(characters[start].codePointAt(0))) start += 1;
22	  while (end > start && isPySpace(characters[end - 1].codePointAt(0))) end -= 1;
23	  return characters.slice(start, end);
24	}
25	
26	/**
27	 * Grammar accepted by `int(x, 10)`:
28	 *   whitespace* [+-]? digit (['_']? digit)* whitespace*
29	 * where `digit` is any Unicode decimal digit and `_` may only separate digits.
30	 *
31	 * @param {string} text
32	 * @returns {bigint}
33	 */
34	export function pyInt(text) {
35	  const characters = stripPySpace(Array.from(text));
36	  let index = 0;
37	  let negative = false;
38	
39	  if (index < characters.length && (characters[index] === '+' || characters[index] === '-')) {
40	    negative = characters[index] === '-';
41	    index += 1;
42	  }
43	
44	  let digits = '';
45	  let previousWasDigit = false;
46	  for (; index < characters.length; index += 1) {
47	    const character = characters[index];
48	    if (character === '_') {
49	      // An underscore must sit between two digits.
50	      if (!previousWasDigit) throw invalidLiteral(text);
51	      previousWasDigit = false;
52	      continue;
53	    }
54	    const value = decimalValue(character.codePointAt(0));
55	    if (value < 0) throw invalidLiteral(text);
56	    digits += String(value);
57	    previousWasDigit = true;
58	  }
59	
60	  if (digits === '' || !previousWasDigit) throw invalidLiteral(text);
61	  const magnitude = BigInt(digits);
62	  return negative ? -magnitude : magnitude;
63	}
64

1	/**
2	 * `repr()` / `str()` for the handful of Python types this program prints.
3	 */
4	
5	import { isPrintable } from './unicodedata.mjs';
6	
7	const SIMPLE_ESCAPES = new Map([
8	  ['\\', '\\\\'],
9	  ['\n', '\\n'],
10	  ['\r', '\\r'],
11	  ['\t', '\\t'],
12	]);
13	
14	function escapeUnprintable(character) {
15	  const codePoint = character.codePointAt(0);
16	  if (codePoint <= 0xff) return `\\x${codePoint.toString(16).padStart(2, '0')}`;
17	  if (codePoint <= 0xffff) return `\\u${codePoint.toString(16).padStart(4, '0')}`;
18	  return `\\U${codePoint.toString(16).padStart(8, '0')}`;
19	}
20	
21	/** `repr()` of a `str`: single quotes unless that forces extra escaping. */
22	export function reprString(text) {
23	  const quote = text.includes("'") && !text.includes('"') ? '"' : "'";
24	  let body = '';
25	  for (const character of text) {
26	    if (character === quote) {
27	      body += `\\${character}`;
28	    } else if (SIMPLE_ESCAPES.has(character)) {
29	      body += SIMPLE_ESCAPES.get(character);
30	    } else if (isPrintable(character)) {
31	      body += character;
32	    } else {
33	      body += escapeUnprintable(character);
34	    }
35	  }
36	  return `${quote}${body}${quote}`;
37	}
38	
39	/** `repr()` of an `int`. Values are carried as BigInt for exact precision. */
40	export function reprInt(value) {
41	  return value.toString();
42	}
43	
44	/** `repr()` of the objects `print()` receives here: `None` or a `list[int]`. */
45	export function reprValue(value) {
46	  if (value === null || value === undefined) return 'None';
47	  if (Array.isArray(value)) return `[${value.map(reprValue).join(', ')}]`;
48	  if (typeof value === 'bigint') return reprInt(value);
49	  if (typeof value === 'string') return reprString(value);
50	  return String(value);
51	}
52	
53	/** Truncate like CPython's `%.<n>R` format code, which counts code points. */
54	export function truncateRepr(text, limit) {
55	  const characters = Array.from(text);
56	  if (characters.length <= limit) return text;
57	  return characters.slice(0, limit).join('');
58	}
