#!/bin/bash
# usage: run.sh <mode>   mode = a | b | c | d | eqa | eqb
# Applies every literal in the corpus in the given position and reports only mismatches.
source /tmp/w14/lits.sh
mode=$1
fail=0
n=0
for lit in "${LITS[@]}"; do
  n=$((n+1))
  case "$mode" in
    a)  args=(--a "$lit" --b 8 --c 5 --d 8) ;;
    b)  args=(--a 165,53 --b "$lit" --c 5 --d 8) ;;
    c)  args=(--a 165,53 --b 8 --c "$lit" --d 8) ;;
    d)  args=(--a 165,53 --b 8 --c 5 --d "$lit") ;;
    eqa) args=("--a=$lit" --b 8 --c 5 --d 8) ;;
    eqb) args=(--a 165,53 "--b=$lit" --c 5 --d 8) ;;
    mid) args=(--a "1,$lit,2" --b 8 --c 5 --d 8) ;;
  esac
  out=$(/tmp/diff.sh "${args[@]}" 2>&1)
  if [ $? -ne 0 ]; then
    fail=$((fail+1))
    echo "=== [$mode #$n] literal bytes: $(printf '%s' "$lit" | od -An -tx1 | tr -d '\n' | tr -s ' ' | cut -c1-120)"
    printf '%s\n' "$out" | head -24
  fi
done
echo "MODE $mode: $n cases, $fail mismatches"

